def use(world: World, actor: Actor, bag: Bag, item_id: str) -> int:
    item = bag.remove(item_id)
    if item.kind == "shield_tonic":
        # Shield tonic increases shield up to cap of 5, does not heal HP
        if actor.shield < 5:
            actor.shield += 1
            world.events.append(Event("shield_tonic", actor.actor_id, amount=1))
            return item.power
        else:
            bag.add(item)
            raise ValueError("shield already at cap")
    elif item.kind != "potion":
        bag.add(item)
        raise ValueError("item is not usable")
    else:
        healed = actor.heal(item.power)
        world.events.append(Event("heal", actor.actor_id, amount=healed))
        return healed
